  'findFirst',
  'findUnique',
  'count',
  'update',
  'updateMany',
  'delete',
  'deleteMany',
  'upsert',
]);

/**
 * Dormant model-query extension; no application path imports it. Requires an
 * already-authorized team, not an arbitrary request value. Intersects caller
 * filters rather than replacing them, and prevents ownership reassignment.
 * Nested writes, raw SQL and non-tenant models are not an authorization boundary.
 */
export function forTeam(prisma: PrismaClient, teamId: number) {
  if (!Number.isSafeInteger(teamId) || teamId <= 0) {
    throw new Error('A team id must be a positive safe integer.');
  }
  return prisma.$extends({
    name: 'team-scoped-model-queries',
    query: {
      $allModels: {
        $allOperations({ model, operation, args, query }) {
          if (!tenantModels.has(model)) return query(args);
          const next: any = { ...args };
          const kind = String(operation);
          if (filtered.has(kind)) {
            // Keep unique selectors outside AND for Prisma WhereUniqueInput.
            // The original filter remains intact, including a conflicting team.
            next.where = { ...next.where, AND: [next.where ?? {}, { teamId }] };

