it('intersects reads, unique lookups, count and adversarial OR/NOT filters', async () => {
  expect(
    (await scoped.externalSource.findMany()).map((row) => row.id),
  ).toEqual([own]);
  const input = {
    where: { OR: [{ teamId: 2 }, { id: own }], NOT: { id: other } },
  };
  const original = structuredClone(input);
  expect(
    (await scoped.externalSource.findMany(input)).map((row) => row.id),
  ).toEqual([own]);
  expect(input).toEqual(original);
  expect(
    await scoped.externalSource.findMany({ where: { teamId: 2 } }),
  ).toEqual([]);
  expect(await scoped.externalSource.findFirst()).toMatchObject({ id: own });
  expect(
    await scoped.externalSource.findFirst({ where: { teamId: 2 } }),
  ).toBeNull();
  expect(
    await scoped.externalSource.findUnique({ where: { id: other } }),
  ).toBeNull();
  expect(
    await scoped.externalSource.findUnique({ where: { id: own } }),
  ).toMatchObject({ teamId: 1 });
  expect(await scoped.externalSource.count()).toBe(1);
  expect(await scoped.externalSource.count({ where: { teamId: 2 } })).toBe(0);
});

it('forces ownership for single create and both createMany forms without mutating input', async () => {
  const input = { data: data(2) };
  const original = structuredClone(input);
  expect(await scoped.externalSource.create(input)).toMatchObject({
    teamId: 1,
  });
  expect(input).toEqual(original);
  const single = data(2);
  await scoped.externalSource.createMany({ data: single });
  const array = [data(2), data(2)];
  await scoped.externalSource.createMany({ data: array });

  expect(await base.externalSource.count({ where: { teamId: 1 } })).toBe(5);
  expect(await base.externalSource.count({ where: { teamId: 2 } })).toBe(1);
  expect(single.teamId).toBe(2);
  expect(array.map((row) => row.teamId)).toEqual([2, 2]);
});

it('scopes updates and bulk updates, including attempted ownership reassignment', async () => {
  await expect(
    scoped.externalSource.update({
      where: { id: other },
      data: { name: 'changed' },
    }),
  ).rejects.toMatchObject({ code: 'P2025' });
  expect(
    await scoped.externalSource.updateMany({
      where: { teamId: 2 },
      data: { name: 'changed' },
    }),
  ).toEqual({ count: 0 });
  expect(
    await scoped.externalSource.update({
      where: { id: own },
      data: { teamId: { set: 2 }, name: 'owned' },
    }),
  ).toMatchObject({ teamId: 1, name: 'owned' });
  expect(
    await scoped.externalSource.updateMany({
      data: { teamId: 2, name: 'bulk owned' },
    }),
  ).toEqual({ count: 1 });
  expect(
    await base.externalSource.findUnique({ where: { id: other } }),
  ).toMatchObject({ teamId: 2, name: 'Harbor Light source' });
  expect(
    await base.externalSource.findUnique({ where: { id: own } }),
  ).toMatchObject({ teamId: 1, name: 'bulk owned' });
});

it('scopes delete and deleteMany without touching another team', async () => {
  await expect(

    scoped.externalSource.delete({ where: { id: other } }),
  ).rejects.toMatchObject({ code: 'P2025' });
  expect(
    await scoped.externalSource.deleteMany({ where: { teamId: 2 } }),
  ).toEqual({ count: 0 });
  expect(
    await scoped.externalSource.delete({ where: { id: own } }),
  ).toMatchObject({ id: own });
  await scoped.externalSource.create({ data: data(1) });
  expect(await scoped.externalSource.deleteMany()).toEqual({ count: 1 });
  expect(await base.externalSource.count()).toBe(1);
  expect(
    await base.externalSource.findUnique({ where: { id: other } }),
  ).toMatchObject({ teamId: 2 });
});

it('qualifies both upsert paths and refuses an upsert targeting another team', async () => {
  expect(
    await scoped.externalSource.upsert({
      where: { id: own },
      create: data(2),
      update: { teamId: 2 },
    }),
  ).toMatchObject({ id: own, teamId: 1 });
  const id = randomUUID();
  expect(
    await scoped.externalSource.upsert({
      where: { id },
      create: data(2, id),
      update: {},
    }),
  ).toMatchObject({ id, teamId: 1 });
  await expect(
    scoped.externalSource.upsert({
      where: { id: other },
      create: data(2, other),
      update: { name: 'changed' },
    }),
  ).rejects.toMatchObject({ code: 'P2002' });
  expect(

      await base.externalSource.findUnique({ where: { id: other } }),
    ).toMatchObject({ teamId: 2, name: 'Harbor Light source' });
  });

  it('leaves non-tenant model operations unchanged and rejects unqualified tenant operations', async () => {
    const name = randomUUID();
    const created = await scoped.layout.create({
      data: { name, componentType: 'harbor-light', settings: '{}' },
    });
    expect(
      await scoped.layout.findUnique({ where: { id: created.id } }),
    ).toEqual(await base.layout.findUnique({ where: { id: created.id } }));
    await expect(
      scoped.externalSource.aggregate({ _count: true }),
    ).rejects.toThrow('not qualified');
  });
});

